package android.graphics;
public final class Rect {public int left,top,right,bottom;public Rect(){}public Rect(int l,int t,int r,int b){set(l,t,r,b);}public Rect(Rect r){this(r.left,r.top,r.right,r.bottom);}public void set(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;}public int width(){return right-left;}public int height(){return bottom-top;}public boolean isEmpty(){return left>=right||top>=bottom;}public boolean contains(int x,int y){return x>=left&&x<right&&y>=top&&y<bottom;}public void scale(float scale){if(scale!=1){left=(int)(left*scale+0.5f);top=(int)(top*scale+0.5f);right=(int)(right*scale+0.5f);bottom=(int)(bottom*scale+0.5f);}}}
